window.BF=window.BF||{};window.BF['4']=[{"id":"g4-1","src":"본문","where":"섹션1: ① 신경 임플란트와 AI (Intro)","en":"Traditionally, researchers have studied various functions of neural implants, which are medical devices like computer chips that can be implanted in the nervous system.","ko":"전통적으로 연구자들은 신경 임플란트의 다양한 기능을 연구해 왔는데, 신경 임플란트는 신경계에 이식될 수 있는, 컴퓨터 칩 같은 의료 기기이다.","v":[{"en":"Neural implants are chip-like medical devices that can be implanted in the nervous system, and researchers have traditionally studied their various functions.","same":true,"ko":"신경 임플란트는 신경계에 이식될 수 있는 칩 같은 의료 기기이며, 연구자들은 전통적으로 그것의 다양한 기능을 연구해 왔다.","n":"which절을 앞으로 빼서 and로 연결, their = neural implants의","sw":[["which are medical devices like computer chips","are chip-like medical devices","컴퓨터 칩 같은 의료 기기인(관계절) ↔ 칩 같은 의료 기기이다(독립절)"],["researchers have studied various functions of neural implants","researchers have traditionally studied their various functions","연구자들은 신경 임플란트의 다양한 기능을 연구해 왔다 ↔ 연구자들은 전통적으로 그것의 다양한 기능을 연구해 왔다"]]},{"en":"Not until recently have researchers begun to study the various functions of neural implants.","same":false,"ko":"최근에서야 비로소 연구자들은 신경 임플란트의 다양한 기능을 연구하기 시작했다.","diff":["Traditionally, researchers have studied","Not until recently have researchers begun to study","전통적으로(오래전부터) 연구해 왔다","최근에서야 비로소 연구하기 시작했다"],"y":"\"Traditionally, researchers have studied various functions of neural implants\" (전통적으로 연구자들은 신경 임플란트의 다양한 기능을 연구해 왔다)\n원문은 오래전부터 연구해 왔다고 했는데, 바꾼 문장은 최근에야 시작했다고 해서 달라요.\n부정어 도치(시점): Not until recently 도치 = '최근에서야 비로소'. 어휘가 원문과 거의 같아 같은 말처럼 보이지만 시점이 정반대","t":"부정어 도치(시점)"},{"en":"Various functions of neural implants have traditionally been studied by researchers.","same":true,"ko":"신경 임플란트의 다양한 기능은 전통적으로 연구자들에 의해 연구되어 왔다.","n":"능동태를 수동태로 바꿔도 같은 내용","sw":[["researchers have studied various functions of neural implants","Various functions of neural implants have traditionally been studied by researchers","연구자들이 기능을 연구했다 ↔ 기능이 연구자들에 의해 연구되었다"]]},{"en":"Researchers have traditionally limited their study of neural implants to a single function.","same":false,"ko":"연구자들은 전통적으로 신경 임플란트 연구를 단 하나의 기능에만 한정해 왔다.","diff":["researchers have studied various functions of neural implants","limited their study of neural implants to a single function","연구 범위: 신경 임플란트의 다양한 기능","연구 범위: 단 하나의 기능으로 한정"],"y":"\"researchers have studied various functions of neural implants\" (연구자들은 신경 임플란트의 다양한 기능을 연구해 왔다)\n원문은 여러 기능을 연구해 왔다고 했는데, 바꾼 문장은 한 가지 기능에만 한정했다고 해서 달라요.\n범위 좁힘: traditionally·researchers·study가 그대로라 같은 말처럼 보이지만, various(다양한) → a single(하나)로 범위가 줄어든 게 함정","t":"범위 좁힘"},{"en":"Neural implants, which researchers have traditionally studied, are computer chips rather than medical devices.","same":false,"ko":"연구자들이 전통적으로 연구해 온 신경 임플란트는 의료 기기라기보다는 컴퓨터 칩이다.","diff":["medical devices like computer chips","computer chips rather than medical devices","컴퓨터 칩 같은 의료 기기(정체는 의료 기기)","의료 기기가 아니라 컴퓨터 칩"],"y":"\"which are medical devices like computer chips\" (그것은 컴퓨터 칩 같은 의료 기기이다)\n원문에서 임플란트의 정체는 의료 기기이고 칩은 비유일 뿐인데, 바꾼 문장은 의료 기기가 아니라고 해서 달라요.\n정의 뒤집기: like(~ 같은)는 비유. A like B는 'A이다'이지 'B이다'가 아님. 두 단어가 모두 원문에 있어 속기 쉬움","t":"정의 뒤집기"},{"en":"Neural implants are medical devices, similar to computer chips, that can be placed in the nervous system.","same":true,"ko":"신경 임플란트는 컴퓨터 칩과 비슷한, 신경계에 넣을 수 있는 의료 기기이다.","n":"관계대명사 which절의 정의를 독립 문장으로 옮긴 같은 내용","sw":[["like computer chips","similar to computer chips","컴퓨터 칩 같은 ↔ 컴퓨터 칩과 비슷한"],["can be implanted in","can be placed in","이식될 수 있다 ↔ 넣어질 수 있다"]]}]},{"id":"g4-2","src":"본문","where":"섹션1: ① 신경 임플란트와 AI (Intro)","en":"But here's the exciting part: with the rapid advancement of artificial intelligence (AI), researchers have begun to integrate AI into neural implants.","ko":"하지만 흥미로운 점은 이것이다. 인공지능(AI)이 빠르게 발전하면서 연구자들은 AI를 신경 임플란트에 통합하기 시작했다.","v":[{"en":"The quick development of AI has led researchers to start putting AI into neural implants.","same":true,"ko":"AI의 빠른 발전은 연구자들이 AI를 신경 임플란트에 넣기 시작하게 만들었다.","n":"원인을 주어로: A has led B to ~ (A 때문에 B가 ~하게 됨)","sw":[["the rapid advancement of artificial intelligence (AI)","The quick development of AI","인공지능의 급속한 발전 ↔ AI의 빠른 발전"],["have begun to integrate AI into neural implants","start putting AI into neural implants","AI를 신경 임플란트에 통합하기 시작했다 ↔ AI를 신경 임플란트에 넣기 시작하다"]]},{"en":"Thanks to the rapid advancement of neural implants, researchers have begun to integrate them with AI.","same":false,"ko":"신경 임플란트가 빠르게 발전한 덕분에 연구자들은 그것을 AI와 통합하기 시작했다.","diff":["with the rapid advancement of artificial intelligence (AI)","Thanks to the rapid advancement of neural implants","빠르게 발전한 것: 인공지능(AI)","빠르게 발전한 것: 신경 임플란트"],"y":"\"with the rapid advancement of artificial intelligence (AI)\" (인공지능이 빠르게 발전하면서)\n원문에서 빠르게 발전한 건 AI인데, 바꾼 문장은 신경 임플란트가 빠르게 발전했다고 해서 달라요.\n원인의 주체 바꿈: 'rapid advancement', 'integrate'가 그대로 있고 결과(통합 시작)도 맞아서 속기 쉬움. 무엇이 발전했는지 꼭 확인","t":"원인의 주체 바꿈"},{"en":"As artificial intelligence has advanced rapidly, researchers have started to combine AI with neural implants.","same":true,"ko":"인공지능이 빠르게 발전하면서 연구자들은 AI를 신경 임플란트와 결합하기 시작했다.","n":"전치사구(with + 명사)를 접속사절(As + 주어 + 동사)로 바꾼 같은 내용","sw":[["with the rapid advancement of artificial intelligence","As artificial intelligence has advanced rapidly","인공지능의 급속한 발전과 함께 ↔ 인공지능이 빠르게 발전하면서"],["begun to integrate AI into","started to combine AI with","~에 통합하기 시작했다 ↔ ~와 결합하기 시작했다"]]},{"en":"According to the writer, it is exciting that researchers have started integrating AI into neural implants.","same":true,"ko":"글쓴이에 따르면, 연구자들이 AI를 신경 임플란트에 통합하기 시작했다는 것은 흥미로운 일이다.","n":"the exciting part(흥미로운 점) = it is exciting that ~","sw":[["here's the exciting part","it is exciting that","흥미로운 점은 이것이다 ↔ ~라는 것은 흥미롭다"],["have begun to integrate","have started integrating","통합하기 시작했다 ↔ 통합하기 시작했다(begin = start)"]]},{"en":"Researchers are planning to integrate AI into neural implants once AI has advanced rapidly enough.","same":false,"ko":"연구자들은 AI가 충분히 빠르게 발전하고 나면 AI를 신경 임플란트에 통합할 계획이다.","diff":["researchers have begun to integrate AI","Researchers are planning to integrate AI","이미 통합하기 시작했다(현재완료)","앞으로 통합할 계획이다(미래)"],"y":"\"researchers have begun to integrate AI into neural implants\" (연구자들은 AI를 신경 임플란트에 통합하기 시작했다)\n원문은 이미 통합을 시작했다고 했는데, 바꾼 문장은 아직 계획 단계라고 해서 달라요.\n시제(이미 시작 vs 앞으로 계획): have begun은 '벌써 시작됨'. 조건(once)을 붙여 미래로 미루면 같은 말처럼 보여도 다름","t":"시제(이미 시작 vs 앞으로 계획)"},{"en":"It is because researchers have begun to integrate AI into neural implants that AI has advanced so rapidly.","same":false,"ko":"AI가 그렇게 빠르게 발전한 것은 연구자들이 AI를 신경 임플란트에 통합하기 시작했기 때문이다.","diff":["with the rapid advancement of artificial intelligence (AI), researchers have begun","It is because researchers have begun to integrate AI into neural implants that AI has advanced","AI의 빠른 발전 → 통합 시작(원인 → 결과)","통합 시작 → AI의 빠른 발전(원인과 결과를 뒤집음)"],"y":"\"with the rapid advancement of artificial intelligence (AI), researchers have begun to integrate AI into neural implants\" (인공지능이 빠르게 발전하면서 연구자들은 AI를 임플란트에 통합하기 시작했다)\n원문은 AI가 발전해서 통합을 시작했다는 순서인데, 바꾼 문장은 통합 때문에 AI가 발전했다고 해서 달라요.\n인과 뒤집기(강조구문): It is because ~ that 강조구문으로 원인과 결과 자리만 맞바꿈. 단어가 전부 원문 그대로라 속기 쉬움","t":"인과 뒤집기(강조구문)"}]},{"id":"g4-3","src":"본문","where":"섹션2: ② 의료 분야 활용","en":"For instance, neural implants are used to treat brain disorders like Parkinson's disease. These implants electrically stimulate targeted regions of the brain at the right time with the help of AI to restore normal brain activity.","ko":"예를 들어, 신경 임플란트는 파킨슨병 같은 뇌 질환을 치료하는 데 사용된다. 이 임플란트는 AI의 도움을 받아 적절한 때에 뇌의 표적 부위를 전기로 자극하여 정상적인 뇌 활동을 회복시킨다.","v":[{"en":"The implants electrically stimulate targeted regions of the brain not to restore normal brain activity but to help AI analyze it.","same":false,"ko":"이 임플란트는 정상적인 뇌 활동을 회복시키기 위해서가 아니라 AI가 그것을 분석하도록 돕기 위해 뇌의 표적 부위를 전기로 자극한다.","diff":["to restore normal brain activity","not to restore normal brain activity but to help AI analyze it","목적: 정상적인 뇌 활동 회복","목적: 회복이 아니라 AI의 분석을 돕는 것"],"y":"\"with the help of AI to restore normal brain activity\" (AI의 도움을 받아 정상적인 뇌 활동을 회복시키기 위해)\n원문의 목적은 뇌 활동 회복이고 AI는 돕는 쪽인데, 바꾼 문장은 목적도 아니라고 하고 돕는 방향도 뒤집어서 달라요.\n목적·도움 방향 뒤집기: with the help of AI = AI가 임플란트를 도움. not A but B에서 B가 진짜 목적. 단어는 원문 그대로라 방향을 놓치기 쉬움","t":"목적·도움 방향 뒤집기"},{"en":"Brain disorders such as Parkinson's disease can be treated with neural implants.","same":true,"ko":"파킨슨병과 같은 뇌 질환은 신경 임플란트로 치료될 수 있다.","n":"A is used to treat B = B can be treated with A","sw":[["neural implants are used to treat brain disorders like Parkinson's disease","Brain disorders such as Parkinson's disease can be treated with neural implants","신경 임플란트가 뇌 질환 치료에 사용된다 ↔ 뇌 질환이 신경 임플란트로 치료될 수 있다"]]},{"en":"With AI's help, the implants send electrical signals to specific parts of the brain at the proper moment so that normal brain activity can return.","same":true,"ko":"AI의 도움으로 임플란트는 적절한 순간에 뇌의 특정 부위에 전기 신호를 보내 정상적인 뇌 활동이 돌아올 수 있게 한다.","n":"목적의 to부정사 = so that ~ can 절","sw":[["electrically stimulate targeted regions of the brain","send electrical signals to specific parts of the brain","뇌의 표적 부위를 전기로 자극하다 ↔ 뇌의 특정 부위에 전기 신호를 보내다"],["at the right time","at the proper moment","적시에 ↔ 적절한 순간에"],["to restore normal brain activity","so that normal brain activity can return","정상적인 뇌 활동을 회복시키기 위해 ↔ 정상적인 뇌 활동이 돌아올 수 있도록"]]},{"en":"The purpose of electrically stimulating parts of the brain with these implants is to bring brain activity back to normal.","same":true,"ko":"이 임플란트로 뇌의 일부를 전기로 자극하는 목적은 뇌 활동을 정상으로 되돌리는 것이다.","n":"목적(to restore)을 The purpose ~ is to ~로 명사화한 같은 내용","sw":[["electrically stimulate targeted regions of the brain","electrically stimulating parts of the brain","뇌의 표적 부위를 전기로 자극하다 ↔ 뇌의 일부를 전기로 자극하는 것"],["to restore normal brain activity","to bring brain activity back to normal","정상적인 뇌 활동을 회복시키다 ↔ 뇌 활동을 정상으로 되돌리다"]]},{"en":"Once AI has helped restore normal brain activity, these implants electrically stimulate targeted regions of the brain.","same":false,"ko":"AI가 정상적인 뇌 활동을 회복하도록 도운 다음에, 이 임플란트가 뇌의 표적 부위를 전기로 자극한다.","diff":["to restore normal brain activity","Once AI has helped restore normal brain activity","전기 자극의 목적: 정상적인 뇌 활동 회복(자극 → 회복)","회복이 먼저 일어난 뒤에 자극(회복 → 자극)"],"y":"\"electrically stimulate targeted regions of the brain at the right time with the help of AI to restore normal brain activity\" (AI의 도움을 받아 적절한 때에 뇌의 표적 부위를 전기로 자극하여 정상적인 뇌 활동을 회복시킨다)\n원문은 자극해서 그 결과로 뇌 활동을 회복시킨다고 했는데, 바꾼 문장은 회복이 끝난 뒤에 자극한다고 해서 순서가 거꾸로예요.\n선후 뒤집기: AI·회복·자극 단어가 모두 들어 있어 같은 말 같지만, to부정사(목적·결과)를 Once(~한 다음에)로 바꿔 순서를 뒤집은 게 함정","t":"선후 뒤집기"},{"en":"Only without the help of AI can these implants stimulate targeted regions of the brain at the right time.","same":false,"ko":"AI의 도움 없이만 이 임플란트는 적절한 때에 뇌의 표적 부위를 자극할 수 있다.","diff":["with the help of AI","Only without the help of AI","AI의 도움을 받아","AI의 도움 없이만"],"y":"\"electrically stimulate targeted regions of the brain at the right time with the help of AI\" (AI의 도움을 받아 적절한 때에 뇌의 표적 부위를 전기로 자극한다)\n원문은 AI의 도움을 받아 자극한다고 했는데, 바꾼 문장은 AI 없이만 가능하다고 해서 달라요.\nOnly 도치(조건 뒤집기): Only + 부사구 + 조동사 도치. 'the help of AI'가 그대로 보여 같은 말로 착각하기 쉬움, without을 놓치지 말 것","t":"Only 도치(조건 뒤집기)"}]},{"id":"g4-4","src":"본문","where":"섹션2: ② 의료 분야 활용","en":"In addition, paralyzed people can have the ability to walk again with the help of a “digital bridge” between two implants inserted into their brain and spine. When they think about moving their legs, the AI analyzes the brain signals and sends them to their legs through the implants. Similarly, those who have lost their arms can use artificial arms operated by the same mechanism.","ko":"또한 마비된 사람들은 뇌와 척추에 삽입된 두 임플란트 사이의 ‘디지털 브릿지’ 덕분에 다시 걸을 수 있게 될 수 있다. 그들이 다리를 움직이려고 생각하면, AI가 뇌 신호를 분석해 그 신호를 임플란트를 통해 다리로 보낸다. 마찬가지로, 팔을 잃은 사람들은 같은 원리로 작동하는 인공 팔을 사용할 수 있다.","v":[{"en":"It is the implants, not the AI, that analyze the brain signals before sending them to the legs.","same":false,"ko":"뇌 신호를 다리로 보내기 전에 분석하는 것은 AI가 아니라 임플란트이다.","diff":["the AI analyzes the brain signals","It is the implants, not the AI, that analyze the brain signals","뇌 신호를 분석하는 주체: AI","분석하는 주체: AI가 아니라 임플란트"],"y":"\"the AI analyzes the brain signals and sends them to their legs through the implants\" (AI가 뇌 신호를 분석해 임플란트를 통해 다리로 보낸다)\n원문에서 신호를 분석하는 건 AI이고 임플란트는 통로인데, 바꾼 문장은 임플란트가 분석한다고 해서 달라요.\n주체 바꿈(강조구문): through the implants = 임플란트를 '통해서'(통로). 분석자와 통로를 바꾸면 오답","t":"주체 바꿈(강조구문)"},{"en":"A “digital bridge” connecting implants in the brain and spine can help paralyzed people walk again.","same":true,"ko":"뇌와 척추의 임플란트를 연결하는 ‘디지털 브릿지’는 마비된 사람들이 다시 걷도록 도울 수 있다.","n":"with the help of A = A can help ~ (도와주는 것을 주어로)","sw":[["with the help of a “digital bridge”","A “digital bridge”","‘디지털 브릿지’의 도움으로 ↔ ‘디지털 브릿지’가(주어)"],["between two implants inserted into their brain and spine","connecting implants in the brain and spine","뇌와 척추에 삽입된 두 임플란트 사이의 ↔ 뇌와 척추의 임플란트를 연결하는"],["have the ability to walk again","walk again","다시 걸을 수 있는 능력을 갖다 ↔ 다시 걷다"]]},{"en":"The brain signals produced when people think about moving their legs are analyzed by AI and delivered to their legs through the implants.","same":true,"ko":"사람들이 다리를 움직이려고 생각할 때 생기는 뇌 신호는 AI에 의해 분석되어 임플란트를 통해 다리로 전달된다.","n":"능동태 → 수동태, them = the brain signals","sw":[["the AI analyzes the brain signals","are analyzed by AI","AI가 뇌 신호를 분석한다 ↔ (뇌 신호가) AI에 의해 분석된다"],["sends them to their legs through the implants","delivered to their legs through the implants","그것들을 임플란트를 통해 다리로 보낸다 ↔ 임플란트를 통해 다리로 전달된다"]]},{"en":"People who have lost their arms can also use artificial arms that work in the same way.","same":true,"ko":"팔을 잃은 사람들도 같은 방식으로 작동하는 인공 팔을 사용할 수 있다.","n":"Similarly = also, the same mechanism = the same way","sw":[["Similarly","also","마찬가지로 ↔ ~도"],["operated by the same mechanism","that work in the same way","같은 원리로 작동되는 ↔ 같은 방식으로 작동하는"]]},{"en":"When paralyzed people think about moving their legs, signals from their legs are analyzed by the AI and sent to their brain.","same":false,"ko":"마비된 사람들이 다리를 움직이려고 생각하면, 다리에서 나온 신호가 AI에 의해 분석되어 뇌로 보내진다.","diff":["the AI analyzes the brain signals and sends them to their legs","signals from their legs are analyzed by the AI and sent to their brain","뇌 신호 → 다리로","다리 신호 → 뇌로"],"y":"\"the AI analyzes the brain signals and sends them to their legs\" (AI가 뇌 신호를 분석해 그 신호를 다리로 보낸다)\n원문은 뇌에서 다리로 신호가 가는데, 바꾼 문장은 다리에서 뇌로 간다고 해서 방향이 반대예요.\n방향 뒤집기(수동태): 수동태로 문장 틀을 바꾸면서 출발지와 도착지만 맞바꿈. analyzed by the AI가 맞아서 속기 쉬움","t":"방향 뒤집기(수동태)"},{"en":"For paralyzed people to walk again, a “digital bridge” has to connect three implants: one each in the brain, the spine, and the legs.","same":false,"ko":"마비된 사람들이 다시 걸으려면 ‘디지털 브릿지’가 뇌, 척추, 다리에 하나씩 있는 세 개의 임플란트를 연결해야 한다.","diff":["two implants inserted into their brain and spine","three implants: one each in the brain, the spine, and the legs","임플란트 2개: 뇌와 척추","임플란트 3개: 뇌, 척추, 다리"],"y":"\"a “digital bridge” between two implants inserted into their brain and spine\" (뇌와 척추에 삽입된 두 임플란트 사이의 ‘디지털 브릿지’)\n원문은 임플란트가 뇌와 척추에 두 개라고 했는데, 바꾼 문장은 다리까지 세 개라고 해서 달라요.\n수치·위치 바꿈: 원문에 'sends them to their legs'(다리로 보낸다)가 있어 다리에도 임플란트가 있다고 착각하기 쉬움. 신호가 다리로 가는 것과 다리에 임플란트가 있는 것은 다름","t":"수치·위치 바꿈"}]},{"id":"g4-5","src":"본문","where":"섹션3: ③ 미래 전망","en":"The success of AI-powered neural implants in health care is also expected to spread to other industries. Some futurists predict that these implants will become commercially available in the next 20 to 30 years and significantly change our daily lives.","ko":"의료 분야에서 AI 기반 신경 임플란트가 거둔 성공은 다른 산업으로도 퍼질 것으로 예상된다. 일부 미래학자들은 이 임플란트가 향후 20~30년 안에 상용화되어 우리의 일상생활을 크게 바꿀 것이라고 예측한다.","v":[{"en":"Having succeeded in other industries, AI-powered neural implants are now expected to spread to health care.","same":false,"ko":"다른 산업에서 성공을 거둔 AI 기반 신경 임플란트는 이제 의료 분야로 퍼질 것으로 예상된다.","diff":["The success of AI-powered neural implants in health care is also expected to spread to other industries","Having succeeded in other industries, AI-powered neural implants are now expected to spread to health care","의료 분야의 성공 → 다른 산업으로","다른 산업의 성공 → 의료 분야로"],"y":"\"The success of AI-powered neural implants in health care is also expected to spread to other industries\" (의료 분야에서 AI 기반 신경 임플란트가 거둔 성공은 다른 산업으로도 퍼질 것으로 예상된다)\n원문은 의료 분야에서 다른 산업으로 퍼진다고 했는데, 바꾼 문장은 반대로 다른 산업에서 의료 분야로 간다고 해서 달라요.\n출발점·도착점 뒤집기: 분사구문(Having succeeded)으로 틀을 바꾸며 health care와 other industries 자리만 맞바꿈. 단어가 다 맞아 보여서 속기 쉬움","t":"출발점·도착점 뒤집기"},{"en":"According to some futurists, these implants will go on sale within the next two or three decades and greatly change everyday life.","same":true,"ko":"일부 미래학자들에 따르면, 이 임플란트는 향후 20~30년 안에 판매되기 시작해 일상생활을 크게 바꿀 것이다.","n":"20 to 30 years = two or three decades, predict that ~ = according to ~","sw":[["Some futurists predict that","According to some futurists","일부 미래학자들은 ~라고 예측한다 ↔ 일부 미래학자들에 따르면"],["become commercially available","go on sale","상용화되다 ↔ 판매되기 시작하다"],["in the next 20 to 30 years","within the next two or three decades","향후 20~30년 안에 ↔ 향후 이삼십 년 안에"]]},{"en":"Futurists generally agree that these implants will become commercially available in the next 20 to 30 years and significantly change our daily lives.","same":false,"ko":"미래학자들은 대체로 이 임플란트가 향후 20~30년 안에 상용화되어 우리의 일상생활을 크게 바꿀 것이라는 데 의견을 같이한다.","diff":["Some futurists predict","Futurists generally agree","일부 미래학자들이 예측한다","미래학자들이 대체로 동의한다(대부분의 의견)"],"y":"\"Some futurists predict that these implants will become commercially available in the next 20 to 30 years\" (일부 미래학자들은 이 임플란트가 향후 20~30년 안에 상용화될 것이라고 예측한다)\n원문은 일부 미래학자들의 예측이라고 했는데, 바꾼 문장은 미래학자들 대부분이 동의한다고 해서 달라요.\n일반화(some → 대부분): 숫자·내용이 모두 원문과 같아 같은 말로 고르기 쉬움. 누가, 얼마나 많은 사람이 그렇게 말했는지까지 확인","t":"일반화(some → 대부분)"},{"en":"It is expected that the success of AI-powered neural implants in health care will also spread to other industries.","same":true,"ko":"의료 분야에서 AI 기반 신경 임플란트의 성공이 다른 산업으로도 퍼질 것으로 예상된다.","n":"A is expected to ~ = It is expected that A will ~","sw":[["is also expected to spread to other industries","will also spread to other industries","다른 산업으로도 퍼질 것으로 예상된다 ↔ (예상되기를) 다른 산업으로도 퍼질 것이다"]]},{"en":"Some futurists expect these implants to reach the market in the next 20 to 30 years and to bring significant changes to our daily lives.","same":true,"ko":"일부 미래학자들은 이 임플란트가 향후 20~30년 안에 시장에 나오고, 우리의 일상생활에 큰 변화를 가져올 것이라고 예상한다.","n":"predict that ~ will = expect ~ to, significantly change(부사+동사) = bring significant changes(형용사+명사)","sw":[["predict that these implants will become commercially available","expect these implants to reach the market","이 임플란트가 상용화될 것이라고 예측한다 ↔ 이 임플란트가 시장에 나올 것이라고 예상한다"],["significantly change our daily lives","bring significant changes to our daily lives","우리의 일상생활을 크게 바꾸다 ↔ 우리의 일상생활에 큰 변화를 가져오다"]]},{"en":"Some futurists say that these implants, now commercially available, will significantly change our daily lives in the next 20 to 30 years.","same":false,"ko":"일부 미래학자들은 지금 상용화되어 있는 이 임플란트가 향후 20~30년 안에 우리의 일상생활을 크게 바꿀 것이라고 말한다.","diff":["will become commercially available in the next 20 to 30 years","now commercially available","상용화 시점: 앞으로 20~30년 안에(아직 아님)","상용화 시점: 지금 이미 상용화됨"],"y":"\"these implants will become commercially available in the next 20 to 30 years\" (이 임플란트가 향후 20~30년 안에 상용화될 것이다)\n원문은 상용화가 앞으로 20~30년 안에 일어날 일이라고 했는데, 바꾼 문장은 지금 이미 상용화되어 있다고 해서 달라요.\n시점 이동(앞으로 → 이미): 20~30년이라는 숫자는 그대로 두고 상용화 시점만 현재로 옮긴 게 함정. 숫자가 어느 일에 붙어 있는지 확인","t":"시점 이동(앞으로 → 이미)"}]},{"id":"g4-6","src":"본문","where":"섹션3: ③ 미래 전망","en":"For example, advances in neural implant technology will make it possible to install in our brains software that can read our minds. This could enable us to play games, type social media messages, and stream music simply by thinking.","ko":"예를 들어, 신경 임플란트 기술이 발전하면 우리의 생각을 읽을 수 있는 소프트웨어를 뇌에 설치하는 것이 가능해질 것이다. 이것으로 우리는 생각만으로 게임을 하고, 소셜 미디어 메시지를 입력하고, 음악을 스트리밍할 수 있게 될 것이다.","v":[{"en":"Thinking alone would not be enough for us to play games, type social media messages, and stream music.","same":false,"ko":"생각만으로는 우리가 게임을 하고, 소셜 미디어 메시지를 입력하고, 음악을 스트리밍하기에 충분하지 않을 것이다.","diff":["simply by thinking","Thinking alone would not be enough","생각만으로(그것으로 충분)","생각만으로는 충분하지 않다"],"y":"\"play games, type social media messages, and stream music simply by thinking\" (생각만으로 게임을 하고, 소셜 미디어 메시지를 입력하고, 음악을 스트리밍할 수 있다)\n원문은 생각만으로 이 모든 걸 할 수 있다고 했는데, 바꾼 문장은 생각만으로는 부족하다고 해서 달라요.\n충분조건 부정: simply = alone(~만으로). 'not enough'가 붙으면 정반대. 활동 세 가지가 그대로 나열돼 같은 말로 착각하기 쉬움","t":"충분조건 부정"},{"en":"Mind-reading software installed in our brains could let us stream music without doing anything but thinking.","same":true,"ko":"뇌에 설치된 생각 읽는 소프트웨어는 우리가 생각하는 것 말고는 아무것도 하지 않고 음악을 스트리밍하게 해 줄 수 있다.","n":"simply by thinking = without doing anything but thinking (생각만으로)","sw":[["could enable us to","could let us","~할 수 있게 해 줄 수 있다 ↔ ~하게 해 줄 수 있다"],["simply by thinking","without doing anything but thinking","생각만으로 ↔ 생각하는 것 말고는 아무것도 하지 않고"]]},{"en":"Thanks to advances in neural implant technology, we will be able to install mind-reading software in our brains.","same":true,"ko":"신경 임플란트 기술의 발전 덕분에 우리는 생각을 읽는 소프트웨어를 뇌에 설치할 수 있게 될 것이다.","n":"A make it possible to ~ = A 덕분에 we will be able to ~","sw":[["advances in neural implant technology will make it possible to install","Thanks to advances in neural implant technology, we will be able to install","기술의 발전이 설치를 가능하게 할 것이다 ↔ 기술의 발전 덕분에 설치할 수 있을 것이다"],["software that can read our minds","mind-reading software","우리 생각을 읽을 수 있는 소프트웨어 ↔ 생각을 읽는 소프트웨어"]]},{"en":"Simply by thinking, we might be able to play games, type social media messages, and stream music.","same":true,"ko":"생각만으로 우리는 게임을 하고, 소셜 미디어 메시지를 입력하고, 음악을 스트리밍할 수 있을지도 모른다.","n":"enable A to ~ = A can(be able to) ~","sw":[["This could enable us to","we might be able to","이것은 우리가 ~할 수 있게 해 줄 수 있다 ↔ 우리는 ~할 수 있을지도 모른다"],["simply by thinking","Simply by thinking","생각만으로 ↔ 생각만으로(문장 앞으로 이동)"]]},{"en":"Mind-reading software can already be installed in our brains thanks to advances in neural implant technology.","same":false,"ko":"신경 임플란트 기술의 발전 덕분에 생각을 읽는 소프트웨어를 이미 우리 뇌에 설치할 수 있다.","diff":["will make it possible","can already be installed","가능하게 할 것이다(미래)","이미 설치할 수 있다(현재)"],"y":"\"advances in neural implant technology will make it possible to install in our brains software that can read our minds\" (신경 임플란트 기술이 발전하면 생각을 읽는 소프트웨어를 뇌에 설치하는 것이 가능해질 것이다)\n원문은 앞으로 가능해질 거라고 했는데, 바꾼 문장은 이미 가능하다고 해서 달라요.\n시제(미래 전망 vs 현재 사실): will make it possible과 can already be의 차이. thanks to로 원인을 그대로 살려 같은 말처럼 보임","t":"시제(미래 전망 vs 현재 사실)"},{"en":"Installing mind-reading software in our brains will lead to advances in neural implant technology.","same":false,"ko":"생각을 읽는 소프트웨어를 뇌에 설치하는 것이 신경 임플란트 기술의 발전으로 이어질 것이다.","diff":["advances in neural implant technology will make it possible to install","Installing mind-reading software in our brains will lead to advances","기술 발전 → 소프트웨어 설치 가능(원인 → 결과)","소프트웨어 설치 → 기술 발전(뒤집음)"],"y":"\"advances in neural implant technology will make it possible to install in our brains software\" (신경 임플란트 기술이 발전하면 뇌에 소프트웨어를 설치하는 것이 가능해질 것이다)\n원문은 기술이 발전해야 설치가 가능해진다는 순서인데, 바꾼 문장은 설치가 기술 발전을 낳는다고 해서 달라요.\n인과 뒤집기: lead to(~로 이어지다)의 앞이 원인, 뒤가 결과. 원문 단어를 그대로 쓰고 원인·결과 자리만 바꿈","t":"인과 뒤집기"}]},{"id":"g4-7","src":"본문","where":"섹션3: ③ 미래 전망","en":"There is also great potential for memory-enhancing brain implants, similar to computer memory chips. Such devices would allow us to capture and enhance memories, and even upload and download them using the digital cloud.","ko":"또한 컴퓨터 메모리 칩과 비슷한, 기억력을 높여 주는 뇌 임플란트도 큰 잠재력이 있다. 이런 장치는 우리가 기억을 저장하고 강화하며, 심지어 디지털 클라우드를 이용해 기억을 업로드하고 다운로드할 수 있게 해 줄 것이다.","v":[{"en":"Memory-enhancing brain implants are already being used to upload and download memories using the digital cloud.","same":false,"ko":"기억력을 높여 주는 뇌 임플란트는 이미 디지털 클라우드를 이용해 기억을 업로드하고 다운로드하는 데 쓰이고 있다.","diff":["would allow us","are already being used","~할 수 있게 해 줄 것이다(가능성)","이미 쓰이고 있다(현재 사실)"],"y":"\"There is also great potential for memory-enhancing brain implants\" (기억력을 높여 주는 뇌 임플란트도 큰 잠재력이 있다)\n원문은 잠재력(앞으로의 가능성)을 말했는데, 바꾼 문장은 이미 쓰이고 있다고 해서 달라요.\n가능성↔사실: potential·would는 '아직 아님'의 신호. 내용(클라우드 업로드)이 원문 그대로라 시점을 놓치기 쉬움","t":"가능성↔사실"},{"en":"With such devices, we would be able to upload and download our memories through the digital cloud.","same":true,"ko":"이런 장치가 있으면 우리는 디지털 클라우드를 통해 기억을 업로드하고 다운로드할 수 있을 것이다.","n":"allow us to ~ = we would be able to ~","sw":[["Such devices would allow us to","With such devices, we would be able to","이런 장치는 우리가 ~하게 해 줄 것이다 ↔ 이런 장치가 있으면 우리는 ~할 수 있을 것이다"],["using the digital cloud","through the digital cloud","디지털 클라우드를 이용해 ↔ 디지털 클라우드를 통해"]]},{"en":"Such devices would allow us to upload and download memories using the digital cloud, but not to capture or enhance them.","same":false,"ko":"이런 장치는 디지털 클라우드를 이용해 기억을 업로드하고 다운로드하게는 해 주겠지만, 기억을 저장하거나 강화하게 해 주지는 않을 것이다.","diff":["allow us to capture and enhance memories","but not to capture or enhance them","기억을 저장하고 강화하게 해 줌","기억을 저장하거나 강화하게는 해 주지 않음"],"y":"\"Such devices would allow us to capture and enhance memories, and even upload and download them\" (이런 장치는 기억을 저장하고 강화하며, 심지어 업로드하고 다운로드하게 해 줄 것이다)\n원문은 저장·강화는 기본이고 업로드·다운로드까지 된다고 했는데, 바꾼 문장은 저장·강화는 안 된다고 해서 달라요.\n일부 부정(even 놓치기): even(심지어)은 '앞의 것에 더해'. 뒷부분만 맞고 기본 기능을 빼 버린 함정, 문장 앞부분이 맞아서 속기 쉬움","t":"일부 부정(even 놓치기)"},{"en":"Brain implants that enhance memory, which are similar to computer memory chips, also have great potential.","same":true,"ko":"컴퓨터 메모리 칩과 비슷한, 기억력을 높여 주는 뇌 임플란트도 큰 잠재력을 가지고 있다.","n":"There is potential for A = A has potential","sw":[["memory-enhancing brain implants","Brain implants that enhance memory","기억력 향상 뇌 임플란트 ↔ 기억력을 높여 주는 뇌 임플란트"],["There is also great potential for","also have great potential","~에 대한 큰 잠재력도 있다 ↔ ~도 큰 잠재력을 가지고 있다"]]},{"en":"These memory implants would make it possible not only to capture and enhance memories but also to move them to and from the digital cloud.","same":true,"ko":"이 기억 임플란트는 기억을 저장하고 강화하는 것뿐 아니라 디지털 클라우드로 옮기고 가져오는 것도 가능하게 할 것이다.","n":"A, and even B = not only A but also B","sw":[["capture and enhance memories, and even","not only to capture and enhance memories but also","기억을 저장하고 강화하며, 심지어 ↔ 기억을 저장하고 강화하는 것뿐 아니라 ~도"],["upload and download them using the digital cloud","move them to and from the digital cloud","디지털 클라우드로 업로드·다운로드하다 ↔ 디지털 클라우드로 옮기고 가져오다"]]},{"en":"Such devices would allow us not only to upload memories but also to download them, though not by using the digital cloud.","same":false,"ko":"이런 장치는 기억을 업로드할 뿐 아니라 다운로드할 수도 있게 해 주겠지만, 디지털 클라우드를 이용해서는 아니다.","diff":["using the digital cloud","though not by using the digital cloud","디지털 클라우드를 이용해","디지털 클라우드를 이용해서는 아니다"],"y":"\"upload and download them using the digital cloud\" (디지털 클라우드를 이용해 기억을 업로드하고 다운로드한다)\n원문은 디지털 클라우드를 이용한다고 했는데, 바꾼 문장은 클라우드를 이용하지 않는다고 해서 달라요.\n수단 부정: not only A but also B로 앞부분을 정확히 패러프레이즈해 놓고 맨 끝 though not에서 수단만 뒤집음","t":"수단 부정"}]},{"id":"g4-8","src":"본문","where":"섹션3: ③ 미래 전망","en":"Finally, AI-powered neural implants would revolutionize the way our brains work. The role of the brain would shift from learning and storing information to processing the vast amounts of data provided by the implants. Instead of simply memorizing information, we would be able to download knowledge, use our creativity to interpret it, and generate new ideas.","ko":"마지막으로, AI 기반 신경 임플란트는 우리 뇌가 작동하는 방식을 혁명적으로 바꿀 것이다. 뇌의 역할은 정보를 학습하고 저장하는 것에서 임플란트가 제공하는 방대한 양의 데이터를 처리하는 것으로 바뀔 것이다. 단순히 정보를 암기하는 대신, 우리는 지식을 다운로드하고, 창의력을 발휘해 그것을 해석하고, 새로운 아이디어를 만들어 낼 수 있을 것이다.","v":[{"en":"We would no longer need to simply memorize information; instead, we could download knowledge and interpret it creatively.","same":true,"ko":"우리는 더 이상 단순히 정보를 암기할 필요가 없고, 대신 지식을 다운로드해 창의적으로 해석할 수 있을 것이다.","n":"use creativity to interpret = interpret creatively","sw":[["Instead of simply memorizing information","no longer need to simply memorize information; instead","단순히 정보를 암기하는 대신 ↔ 더 이상 단순히 암기할 필요가 없고, 대신"],["use our creativity to interpret it","interpret it creatively","창의력을 발휘해 그것을 해석하다 ↔ 그것을 창의적으로 해석하다"]]},{"en":"Even with the implants, we would still need to memorize information before we could download knowledge.","same":false,"ko":"임플란트가 있어도 우리는 지식을 다운로드하기 전에 여전히 정보를 암기해야 할 것이다.","diff":["Instead of simply memorizing information","we would still need to memorize information","단순히 암기하는 대신(암기를 대체)","여전히 암기해야 한다"],"y":"\"Instead of simply memorizing information, we would be able to download knowledge\" (단순히 정보를 암기하는 대신, 우리는 지식을 다운로드할 수 있을 것이다)\n원문은 암기 대신 다운로드한다고 했는데, 바꾼 문장은 여전히 먼저 암기해야 한다고 해서 달라요.\n대체 관계 부정: Instead of A, B = A 말고 B. 'A를 먼저 하고 B'로 바꾸면 오답. memorize·download가 둘 다 나와 같은 말처럼 보임","t":"대체 관계 부정"},{"en":"The role of the brain would shift to learning and storing information, rather than processing the vast amounts of data provided by the implants.","same":false,"ko":"뇌의 역할은 임플란트가 제공하는 방대한 데이터를 처리하기보다는 정보를 학습하고 저장하는 쪽으로 바뀔 것이다.","diff":["from learning and storing information to processing","shift to learning and storing information, rather than processing","학습·저장 → 데이터 처리로","데이터 처리가 아니라 학습·저장으로"],"y":"\"The role of the brain would shift from learning and storing information to processing the vast amounts of data\" (뇌의 역할은 정보를 학습하고 저장하는 것에서 방대한 데이터를 처리하는 것으로 바뀔 것이다)\n원문은 학습·저장에서 처리로 바뀐다고 했는데, 바꾼 문장은 반대로 학습·저장 쪽으로 바뀐다고 해서 달라요.\n변화 방향 뒤집기(from A to B): shift from A to B에서 B가 도착점. rather than을 써서 어순까지 바꾸면 방향이 헷갈리기 쉬움","t":"변화 방향 뒤집기(from A to B)"},{"en":"The implants, rather than our own creativity, would be used to interpret the downloaded knowledge.","same":false,"ko":"다운로드된 지식을 해석하는 데는 우리 자신의 창의력이 아니라 임플란트가 쓰일 것이다.","diff":["use our creativity to interpret it","The implants, rather than our own creativity, would be used to interpret","우리의 창의력으로 해석","창의력이 아니라 임플란트로 해석"],"y":"\"use our creativity to interpret it\" (창의력을 발휘해 그것을 해석한다)\n원문에서 지식을 해석하는 건 우리의 창의력인데, 바꾼 문장은 임플란트가 해석한다고 해서 달라요.\n주체 바꿈: 임플란트는 데이터를 '제공'하는 쪽, 해석은 우리 몫. 수동태(would be used)로 틀을 바꿔 주체가 흐려짐","t":"주체 바꿈"},{"en":"AI-powered neural implants would bring about a revolution in how our brains work.","same":true,"ko":"AI 기반 신경 임플란트는 우리 뇌가 작동하는 방식에 혁명을 일으킬 것이다.","n":"동사 revolutionize → 명사 revolution(명사화), the way = how","sw":[["would revolutionize the way our brains work","would bring about a revolution in how our brains work","뇌가 작동하는 방식을 혁명적으로 바꿀 것이다 ↔ 뇌가 작동하는 방식에 혁명을 일으킬 것이다"]]},{"en":"Rather than learning and storing information, the brain's role would be to process the huge amounts of data that the implants provide.","same":true,"ko":"정보를 학습하고 저장하는 대신, 뇌의 역할은 임플란트가 제공하는 엄청난 양의 데이터를 처리하는 것이 될 것이다.","n":"shift from A to B = Rather than A, B / 과거분사 provided by = that절","sw":[["shift from learning and storing information to processing","Rather than learning and storing information, the brain's role would be to process","정보 학습·저장에서 처리로 바뀌다 ↔ 학습·저장 대신 처리하는 것이 역할이 되다"],["the vast amounts of data provided by the implants","the huge amounts of data that the implants provide","임플란트가 제공하는 방대한 양의 데이터 ↔ 임플란트가 제공하는 엄청난 양의 데이터"]]}]},{"id":"g4-9","src":"본문","where":"섹션4: ④ 윤리적 문제","en":"Before we can fully embrace the era of AI-powered neural implants, many tricky ethical issues should be addressed. The integration of AI technology with the human brain raises concerns about what it means to be human.","ko":"AI 기반 신경 임플란트의 시대를 완전히 받아들이기 전에, 까다로운 윤리적 문제들이 많이 해결되어야 한다. AI 기술을 인간의 뇌와 통합하는 것은 인간이라는 것이 무엇을 의미하는지에 대한 우려를 불러일으킨다.","v":[{"en":"We should address many tricky ethical issues before we can fully accept the era of AI-powered neural implants.","same":true,"ko":"우리는 AI 기반 신경 임플란트의 시대를 완전히 받아들이기 전에 까다로운 윤리적 문제들을 많이 해결해야 한다.","n":"수동태(should be addressed) → 능동태(We should address)","sw":[["many tricky ethical issues should be addressed","We should address many tricky ethical issues","까다로운 윤리적 문제들이 해결되어야 한다 ↔ 우리는 까다로운 윤리적 문제들을 해결해야 한다"],["fully embrace","fully accept","완전히 받아들이다 ↔ 완전히 받아들이다(embrace = accept)"]]},{"en":"Concerns about what it means to be human have led to the integration of AI technology with the human brain.","same":false,"ko":"인간이라는 것이 무엇을 의미하는지에 대한 우려가 AI 기술과 인간 뇌의 통합으로 이어졌다.","diff":["The integration of AI technology with the human brain raises concerns","Concerns about what it means to be human have led to the integration","통합 → 우려를 불러일으킴","우려 → 통합으로 이어짐(뒤집음)"],"y":"\"The integration of AI technology with the human brain raises concerns about what it means to be human\" (AI 기술을 인간의 뇌와 통합하는 것은 인간이라는 것의 의미에 대한 우려를 불러일으킨다)\n원문은 통합이 우려를 낳는다고 했는데, 바꾼 문장은 우려 때문에 통합이 생겼다고 해서 달라요.\n인과 뒤집기: raise(불러일으키다)의 주어가 원인. lead to로 동사를 바꾸며 원인·결과 자리를 맞바꿈","t":"인과 뒤집기"},{"en":"Combining AI technology with the human brain makes people worry about the meaning of being human.","same":true,"ko":"AI 기술을 인간의 뇌와 결합하는 것은 사람들이 인간이라는 것의 의미에 대해 걱정하게 만든다.","n":"명사(integration) → 동명사(Combining), raise concerns = make people worry","sw":[["The integration of AI technology with the human brain","Combining AI technology with the human brain","AI 기술과 인간 뇌의 통합 ↔ AI 기술을 인간의 뇌와 결합하는 것"],["raises concerns about what it means to be human","makes people worry about the meaning of being human","인간이라는 것이 무엇을 의미하는지 우려를 일으킨다 ↔ 인간이라는 것의 의미를 걱정하게 만든다"]]},{"en":"Dealing with many tricky ethical issues should come before our full acceptance of the era of AI-powered neural implants.","same":true,"ko":"많은 까다로운 윤리적 문제를 해결하는 일이 AI 기반 신경 임플란트 시대를 완전히 받아들이는 것보다 먼저 이루어져야 한다.","n":"Before 절 → 명사구(our full acceptance), address = deal with","sw":[["many tricky ethical issues should be addressed","Dealing with many tricky ethical issues should come before","까다로운 윤리적 문제들이 해결되어야 한다 ↔ 까다로운 윤리적 문제를 해결하는 일이 먼저 와야 한다"],["Before we can fully embrace the era","our full acceptance of the era","시대를 완전히 받아들이기 전에(절) ↔ 시대의 완전한 수용(명사구)"]]},{"en":"Since many tricky ethical issues have already been addressed, we can now fully embrace the era of AI-powered neural implants.","same":false,"ko":"까다로운 윤리적 문제들이 이미 많이 해결되었으므로, 이제 우리는 AI 기반 신경 임플란트의 시대를 완전히 받아들일 수 있다.","diff":["many tricky ethical issues should be addressed","many tricky ethical issues have already been addressed","해결되어야 한다(아직 남은 과제)","이미 해결되었다(끝난 일)"],"y":"\"Before we can fully embrace the era of AI-powered neural implants, many tricky ethical issues should be addressed.\" (AI 기반 신경 임플란트의 시대를 완전히 받아들이기 전에 까다로운 윤리적 문제들이 많이 해결되어야 한다)\n원문은 윤리적 문제를 앞으로 해결해야 한다고 했는데, 바꾼 문장은 이미 해결되었다고 해서 달라요.\n해야 할 일 → 이미 한 일: 해결 후 받아들인다는 순서는 맞아서 속기 쉬움. should be addressed(해결되어야 한다)는 아직 안 됐다는 뜻","t":"해야 할 일 → 이미 한 일"},{"en":"Not until we fully embrace the era of AI-powered neural implants should many tricky ethical issues be addressed.","same":false,"ko":"AI 기반 신경 임플란트의 시대를 완전히 받아들이고 나서야 비로소 까다로운 윤리적 문제들이 해결되어야 한다.","diff":["Before we can fully embrace the era","Not until we fully embrace the era","받아들이기 전에 해결","받아들이고 나서야 해결"],"y":"\"Before we can fully embrace the era of AI-powered neural implants, many tricky ethical issues should be addressed\" (AI 기반 신경 임플란트의 시대를 완전히 받아들이기 전에, 까다로운 윤리적 문제들이 많이 해결되어야 한다)\n원문은 받아들이기 전에 문제를 해결해야 한다고 했는데, 바꾼 문장은 받아들인 뒤에야 해결한다고 해서 순서가 반대예요.\n부정어 도치(선후 뒤집기): Not until A + 도치 = 'A하고 나서야 비로소'. 단어가 원문과 거의 같아 before와 같은 뜻으로 착각하기 쉬움","t":"부정어 도치(선후 뒤집기)"}]},{"id":"g4-10","src":"본문","where":"섹션4: ④ 윤리적 문제","en":"Our brains are believed to be central to our identity, existence, and value as human beings. However, an over-reliance on technology may delay our natural development and create confusion about whether we are human, AI, or something in between.","ko":"우리의 뇌는 인간으로서의 정체성, 존재, 가치의 중심이라고 여겨진다. 그러나 기술에 지나치게 의존하면 우리의 자연스러운 발달이 늦어지고, 우리가 인간인지, AI인지, 아니면 그 중간의 무엇인지에 대한 혼란이 생길 수 있다.","v":[{"en":"Our brains are believed to be central to our identity, but not to our value as human beings.","same":false,"ko":"우리의 뇌는 정체성의 중심이라고 여겨지지만, 인간으로서의 가치의 중심이라고 여겨지지는 않는다.","diff":["central to our identity, existence, and value","central to our identity, but not to our value","정체성·존재·가치 모두의 중심","정체성의 중심이지만 가치의 중심은 아님"],"y":"\"Our brains are believed to be central to our identity, existence, and value as human beings\" (우리의 뇌는 인간으로서의 정체성, 존재, 가치의 중심이라고 여겨진다)\n원문은 가치까지 포함해 세 가지 모두의 중심이라고 했는데, 바꾼 문장은 가치는 빼서 달라요.\n일부 부정: 나열된 셋 중 하나만 but not으로 빼는 함정. 앞부분이 원문 그대로라 끝까지 안 읽으면 속음","t":"일부 부정"},{"en":"People believe that our brains are central to who we are and what we are worth as human beings.","same":true,"ko":"사람들은 우리의 뇌가 인간으로서 우리가 누구인지, 그리고 우리의 가치가 무엇인지의 중심이라고 믿는다.","n":"A is believed to be ~ = People believe that A is ~","sw":[["Our brains are believed to be central","People believe that our brains are central","우리의 뇌는 중심이라고 여겨진다 ↔ 사람들은 우리의 뇌가 중심이라고 믿는다"],["our identity","who we are","우리의 정체성 ↔ 우리가 누구인지"]]},{"en":"It is a delay in our natural development that may cause an over-reliance on technology.","same":false,"ko":"기술에 대한 지나친 의존을 일으킬 수 있는 것은 바로 우리의 자연스러운 발달의 지연이다.","diff":["an over-reliance on technology may delay our natural development","It is a delay in our natural development that may cause an over-reliance on technology","지나친 기술 의존 → 발달 지연","발달 지연 → 지나친 기술 의존(뒤집음)"],"y":"\"an over-reliance on technology may delay our natural development\" (기술에 지나치게 의존하면 우리의 자연스러운 발달이 늦어질 수 있다)\n원문은 기술 의존이 발달을 늦춘다고 했는데, 바꾼 문장은 발달 지연이 기술 의존을 낳는다고 해서 원인과 결과가 반대예요.\n인과 뒤집기(강조구문): delay를 명사로 바꾸고 It is ~ that 강조구문을 써서 원인·결과 자리를 맞바꿈. 단어가 같아 같은 말처럼 보임","t":"인과 뒤집기(강조구문)"},{"en":"Depending too heavily on technology could make us confused about whether we are human, AI, or something in between.","same":true,"ko":"기술에 너무 크게 의존하면 우리가 인간인지, AI인지, 그 중간의 무엇인지 헷갈리게 될 수 있다.","n":"create confusion(혼란을 만들다) = make us confused(우리를 헷갈리게 하다)","sw":[["an over-reliance on technology","Depending too heavily on technology","기술에 대한 지나친 의존 ↔ 기술에 너무 크게 의존하는 것"],["create confusion about","make us confused about","~에 대한 혼란을 일으키다 ↔ ~에 대해 우리를 헷갈리게 하다"]]},{"en":"An over-reliance on technology may make it clear that we are something in between human and AI.","same":false,"ko":"기술에 지나치게 의존하면 우리가 인간과 AI의 중간쯤 되는 무엇이라는 것이 분명해질 수 있다.","diff":["create confusion about whether we are human, AI, or something in between","make it clear that we are something in between human and AI","인간인지 AI인지 그 중간인지 혼란이 생김","그 중간이라는 것이 분명해짐"],"y":"\"create confusion about whether we are human, AI, or something in between\" (우리가 인간인지, AI인지, 아니면 그 중간의 무엇인지에 대한 혼란이 생길 수 있다)\n원문은 무엇인지 헷갈리게 된다고 했는데, 바꾼 문장은 중간이라는 게 분명해진다고 해서 달라요.\n혼란↔확정: whether A, B, or C(셋 중 무엇인지)는 답을 모른다는 뜻. 선택지 하나(in between)를 정답처럼 확정하면 오답","t":"혼란↔확정"},{"en":"If we rely too much on technology, our natural development may be slowed down.","same":true,"ko":"우리가 기술에 너무 많이 의존하면 우리의 자연스러운 발달이 늦춰질 수 있다.","n":"명사구 주어(an over-reliance) → if 조건절, 능동 → 수동","sw":[["an over-reliance on technology","If we rely too much on technology","기술에 대한 지나친 의존 ↔ 우리가 기술에 너무 많이 의존하면"],["may delay our natural development","our natural development may be slowed down","자연스러운 발달을 지연시킬 수 있다 ↔ 자연스러운 발달이 늦춰질 수 있다"]]}]},{"id":"g4-11","src":"본문","where":"섹션4: ④ 윤리적 문제","en":"Another critical issue is privacy. There's a risk that organizations or hackers could access personal data without permission through AI-connected implants. This means that our thoughts, emotions, and behaviors could be controlled by hackers.","ko":"또 다른 중요한 문제는 사생활(개인 정보) 보호이다. 기관이나 해커가 AI와 연결된 임플란트를 통해 허가 없이 개인 정보에 접근할 수 있는 위험이 있다. 이는 우리의 생각, 감정, 행동이 해커에게 조종될 수 있다는 것을 의미한다.","v":[{"en":"Through AI-connected implants, hackers have already been controlling people's thoughts, emotions, and behaviors.","same":false,"ko":"AI와 연결된 임플란트를 통해 해커들은 이미 사람들의 생각, 감정, 행동을 조종해 오고 있다.","diff":["could be controlled by hackers","hackers have already been controlling","해커에게 조종될 수 있다(가능성·위험)","해커가 이미 조종해 오고 있다(사실)"],"y":"\"our thoughts, emotions, and behaviors could be controlled by hackers\" (우리의 생각, 감정, 행동이 해커에게 조종될 수 있다)\n원문은 그럴 위험이 있다(could)고 했는데, 바꾼 문장은 이미 일어나고 있다고 해서 달라요.\n가능성↔사실: There's a risk·could는 '아직 일어난 일 아님'. 능동태로 바꾸며 시제만 슬쩍 완료진행형으로 바꿈","t":"가능성↔사실"},{"en":"Hackers could take control of our thoughts, emotions, and behaviors.","same":true,"ko":"해커가 우리의 생각, 감정, 행동을 조종할 수 있다.","n":"수동태(be controlled by hackers) → 능동태(Hackers could take control of)","sw":[["our thoughts, emotions, and behaviors could be controlled by hackers","Hackers could take control of our thoughts, emotions, and behaviors","우리의 생각·감정·행동이 해커에게 조종될 수 있다 ↔ 해커가 우리의 생각·감정·행동을 조종할 수 있다"]]},{"en":"Privacy is another serious problem, since personal data could be accessed without permission through AI-connected implants.","same":true,"ko":"AI와 연결된 임플란트를 통해 개인 정보가 허가 없이 접근될 수 있기 때문에, 사생활 보호는 또 다른 심각한 문제이다.","n":"critical = serious, 능동태 → 수동태 + 이유(since)로 연결","sw":[["Another critical issue is privacy","Privacy is another serious problem","또 다른 중요한 문제는 사생활 보호다 ↔ 사생활 보호는 또 다른 심각한 문제다"],["could access personal data without permission","personal data could be accessed without permission","개인 정보에 허가 없이 접근할 수 있다 ↔ 개인 정보가 허가 없이 접근될 수 있다"]]},{"en":"Not organizations but only hackers could access personal data without permission through AI-connected implants.","same":false,"ko":"기관이 아니라 해커만이 AI와 연결된 임플란트를 통해 허가 없이 개인 정보에 접근할 수 있을 것이다.","diff":["organizations or hackers could access","Not organizations but only hackers could access","기관이나 해커가 접근 가능","기관은 아니고 해커만 접근 가능"],"y":"\"organizations or hackers could access personal data without permission\" (기관이나 해커가 허가 없이 개인 정보에 접근할 수 있다)\n원문은 기관이나 해커 둘 다 접근할 수 있다고 했는데, 바꾼 문장은 기관은 빼서 달라요.\n주체 범위 좁힘: 마지막 문장에 hackers만 나와서 기관은 상관없다고 착각하기 쉬움. or로 묶인 둘 다 확인","t":"주체 범위 좁힘"},{"en":"Organizations could access personal data through AI-connected implants only if people gave them permission.","same":false,"ko":"기관은 사람들이 허가를 해 준 경우에만 AI와 연결된 임플란트를 통해 개인 정보에 접근할 수 있을 것이다.","diff":["without permission","only if people gave them permission","허가 없이","허가를 해 준 경우에만"],"y":"\"access personal data without permission through AI-connected implants\" (AI와 연결된 임플란트를 통해 허가 없이 개인 정보에 접근할 수 있다)\n원문의 위험은 허가 없이 접근하는 것인데, 바꾼 문장은 허가가 있어야만 접근할 수 있다고 해서 반대예요.\n필요조건(only if) 뒤집기: only if = '~해야만'(필요조건). permission이라는 단어가 그대로 있어 같은 말로 보이지만 without과 정반대","t":"필요조건(only if) 뒤집기"},{"en":"Through AI-connected implants, organizations or hackers might get into personal data without permission.","same":true,"ko":"AI와 연결된 임플란트를 통해 기관이나 해커가 허가 없이 개인 정보에 들어갈 수도 있다.","n":"There's a risk that ~ could = ~ might (위험·가능성)","sw":[["There's a risk that organizations or hackers could access","organizations or hackers might get into","기관이나 해커가 접근할 수 있는 위험이 있다 ↔ 기관이나 해커가 들어갈 수도 있다"],["through AI-connected implants","Through AI-connected implants","AI 연결 임플란트를 통해 ↔ (문장 앞으로 이동)"]]}]},{"id":"g4-12","src":"본문","where":"섹션4: ④ 윤리적 문제","en":"There's an additional risk that this technology could lead to even greater social inequality, given that it may not be available to all due to its high cost. Such unequal access to the technology could intensify the division between those who can afford the implants and those who cannot.","ko":"이 기술은 비싼 비용 때문에 모든 사람이 이용하지는 못할 수 있다는 점에서, 사회적 불평등을 훨씬 더 키울 수 있다는 추가적인 위험도 있다. 기술에 대한 이러한 불평등한 접근은 임플란트 비용을 감당할 수 있는 사람과 그렇지 못한 사람 사이의 분열을 심화시킬 수 있다.","v":[{"en":"Not everyone may be able to afford this technology, so it could increase social inequality.","same":true,"ko":"모든 사람이 이 기술의 비용을 감당할 수 있는 것은 아니어서, 이 기술은 사회적 불평등을 키울 수 있다.","n":"이유(given that ~)를 앞으로, 결과를 so로 연결 / 부분 부정 Not everyone","sw":[["it may not be available to all due to its high cost","Not everyone may be able to afford this technology","비싼 비용 때문에 모두가 이용하지 못할 수 있다 ↔ 모두가 비용을 감당할 수 있는 건 아니다"],["lead to even greater social inequality","increase social inequality","사회적 불평등을 훨씬 더 키우다 ↔ 사회적 불평등을 키우다"]]},{"en":"It is growing social inequality that has made this technology so expensive.","same":false,"ko":"이 기술을 그렇게 비싸게 만든 것은 바로 커지는 사회적 불평등이다.","diff":["this technology could lead to even greater social inequality","It is growing social inequality that has made this technology so expensive","비싼 기술 → 불평등 심화","불평등 → 기술이 비싸짐(뒤집음)"],"y":"\"this technology could lead to even greater social inequality, given that it may not be available to all due to its high cost\" (이 기술은 비싼 비용 때문에 모두가 이용하지는 못할 수 있어서 사회적 불평등을 훨씬 더 키울 수 있다)\n원문은 비싼 비용 때문에 불평등이 커진다고 했는데, 바꾼 문장은 불평등 때문에 기술이 비싸졌다고 해서 원인과 결과가 반대예요.\n인과 뒤집기(강조구문): high cost와 inequality가 둘 다 나와 같은 말처럼 보임. lead to·due to의 화살표 방향 확인","t":"인과 뒤집기(강조구문)"},{"en":"Unequal access to the technology has already intensified the division between those who can afford the implants and those who cannot.","same":false,"ko":"기술에 대한 불평등한 접근은 이미 임플란트 비용을 감당할 수 있는 사람과 그렇지 못한 사람 사이의 분열을 심화시켰다.","diff":["could intensify the division","has already intensified the division","분열을 심화시킬 수 있다(가능성)","이미 분열을 심화시켰다(사실)"],"y":"\"Such unequal access to the technology could intensify the division\" (기술에 대한 이러한 불평등한 접근은 분열을 심화시킬 수 있다)\n원문은 앞으로 그럴 수 있다고 했는데, 바꾼 문장은 이미 그렇게 됐다고 해서 달라요.\n가능성↔사실: 나머지가 원문 그대로라 could와 has already의 차이만 보면 됨. risk(위험) 문단은 아직 일어나지 않은 일","t":"가능성↔사실"},{"en":"Because of its high price, this technology may not be available to everyone, which could make social inequality even worse.","same":true,"ko":"비싼 가격 때문에 이 기술은 모든 사람이 이용하지는 못할 수 있고, 이것은 사회적 불평등을 더욱 악화시킬 수 있다.","n":"given that(~라는 점에서) 이유를 앞으로 + lead to greater = make ~ worse","sw":[["due to its high cost","Because of its high price","비싼 비용 때문에 ↔ 비싼 가격 때문에"],["it may not be available to all","this technology may not be available to everyone","모든 사람이 이용하지는 못할 수 있다 ↔ 이 기술은 모든 사람이 이용하지는 못할 수 있다"],["lead to even greater social inequality","make social inequality even worse","사회적 불평등을 훨씬 더 키우다 ↔ 사회적 불평등을 더욱 악화시키다"]]},{"en":"Since no one will be able to afford the technology because of its high cost, it could lead to greater social inequality.","same":false,"ko":"비싼 비용 때문에 아무도 이 기술을 감당할 수 없을 것이므로, 이 기술은 더 큰 사회적 불평등으로 이어질 수 있다.","diff":["it may not be available to all","no one will be able to afford the technology","모두가 이용할 수 있는 건 아니다(부분 부정)","아무도 감당할 수 없다(전체 부정)"],"y":"\"it may not be available to all due to its high cost\" (비싼 비용 때문에 모든 사람이 이용하지는 못할 수 있다)\n원문은 일부는 이용하고 일부는 못 한다(감당할 수 있는 사람과 없는 사람)는 뜻인데, 바꾼 문장은 아무도 못 한다고 해서 달라요.\n부분 부정↔전체 부정: not ... all = '모두 ~인 것은 아니다'(일부는 됨). 아무도 못 쓰면 불평등도 생길 수 없다는 점이 단서","t":"부분 부정↔전체 부정"},{"en":"The gap between people who can pay for the implants and people who cannot could grow wider because of unequal access.","same":true,"ko":"불평등한 접근 때문에 임플란트 비용을 낼 수 있는 사람과 낼 수 없는 사람 사이의 격차가 더 벌어질 수 있다.","n":"intensify the division(분열을 심화시키다) = the gap could grow wider(격차가 벌어지다)","sw":[["could intensify the division","could grow wider","분열을 심화시킬 수 있다 ↔ (격차가) 더 벌어질 수 있다"],["those who can afford the implants","people who can pay for the implants","임플란트 비용을 감당할 수 있는 사람들 ↔ 임플란트 비용을 낼 수 있는 사람들"]]}]},{"id":"g4-13","src":"본문","where":"섹션5: ⑤ 신경 윤리와 댓글","en":"I hope that we can overcome these challenges through careful consideration of neuroethics. This field highlights the social aspects of neural technology and provides possible answers to what should be considered legal and ethical.","ko":"나는 우리가 신경 윤리를 신중하게 고려함으로써 이러한 난제들을 극복할 수 있기를 바란다. 이 분야는 신경 기술의 사회적 측면을 강조하고, 무엇을 합법적이고 윤리적인 것으로 여겨야 하는지에 대해 가능한 답을 제시한다.","v":[{"en":"Neuroethics focuses on the social aspects of neural technology rather than on what should be considered legal and ethical.","same":false,"ko":"신경 윤리는 무엇을 합법적이고 윤리적인 것으로 여겨야 하는지보다는 신경 기술의 사회적 측면에 초점을 둔다.","diff":["highlights the social aspects of neural technology and provides possible answers to what should be considered legal and ethical","focuses on the social aspects of neural technology rather than on what should be considered legal and ethical","사회적 측면 강조 + 합법·윤리 기준에 대한 답 제시(둘 다 함)","사회적 측면에 초점, 합법·윤리 기준은 아님(하나만 함)"],"y":"\"This field highlights the social aspects of neural technology and provides possible answers to what should be considered legal and ethical.\" (이 분야는 신경 기술의 사회적 측면을 강조하고, 무엇을 합법적이고 윤리적인 것으로 여겨야 하는지에 대해 가능한 답을 제시한다)\n원문은 두 가지를 모두 한다(and)고 했는데, 바꾼 문장은 하나만 하고 다른 하나는 아니라고(rather than) 해서 달라요.\n나열 → 대조 바꿈: 두 내용이 모두 원문에 나와 단어만 보면 맞아 보이지만, and(그리고)가 rather than(~보다는)으로 바뀌어 한쪽이 빠진 게 함정","t":"나열 → 대조 바꿈"},{"en":"In the field of neuroethics, the social aspects of neural technology are emphasized.","same":true,"ko":"신경 윤리 분야에서는 신경 기술의 사회적 측면이 강조된다.","n":"highlight = emphasize, 능동태 → 수동태, This field = neuroethics(지시어 풀기)","sw":[["This field highlights the social aspects of neural technology","the social aspects of neural technology are emphasized","이 분야는 신경 기술의 사회적 측면을 강조한다 ↔ 신경 기술의 사회적 측면이 강조된다"],["careful consideration of neuroethics","In the field of neuroethics","신경 윤리를 신중하게 고려함 ↔ 신경 윤리 분야에서(This field가 가리키는 것)"]]},{"en":"The writer hopes that these challenges can be overcome by carefully considering neuroethics.","same":true,"ko":"글쓴이는 신경 윤리를 신중하게 고려함으로써 이러한 난제들이 극복될 수 있기를 바란다.","n":"능동 → 수동, through + 명사 = by + 동명사","sw":[["we can overcome these challenges","these challenges can be overcome","우리가 이러한 난제들을 극복할 수 있다 ↔ 이러한 난제들이 극복될 수 있다"],["through careful consideration of neuroethics","by carefully considering neuroethics","신경 윤리에 대한 신중한 고려를 통해 ↔ 신경 윤리를 신중하게 고려함으로써"]]},{"en":"Neuroethics offers possible answers about what should be regarded as legal and ethical.","same":true,"ko":"신경 윤리는 무엇이 합법적이고 윤리적인 것으로 여겨져야 하는지에 대해 가능한 답을 제시한다.","n":"consider A (to be) B = regard A as B","sw":[["provides possible answers to","offers possible answers about","~에 대한 가능한 답을 제공한다 ↔ ~에 대한 가능한 답을 제시한다"],["should be considered legal and ethical","should be regarded as legal and ethical","합법적이고 윤리적인 것으로 여겨져야 한다 ↔ 합법적이고 윤리적인 것으로 간주되어야 한다"]]},{"en":"Neuroethics has already settled what should be considered legal and ethical.","same":false,"ko":"신경 윤리는 무엇을 합법적이고 윤리적인 것으로 여겨야 하는지를 이미 확정했다.","diff":["provides possible answers","has already settled","가능한 답을 제시(아직 열려 있음)","이미 확정했다"],"y":"\"provides possible answers to what should be considered legal and ethical\" (무엇을 합법적이고 윤리적인 것으로 여겨야 하는지에 대해 가능한 답을 제시한다)\n원문은 '가능한' 답을 내놓는다고 했는데, 바꾼 문장은 이미 결론을 냈다고 해서 달라요.\n가능성↔확정: possible 한 단어가 핵심. 필자도 hope(바란다)라고 해서 아직 해결 전이라는 점이 단서","t":"가능성↔확정"},{"en":"The writer hopes that overcoming these challenges will lead to careful consideration of neuroethics.","same":false,"ko":"필자는 이러한 난제들을 극복하는 것이 신경 윤리에 대한 신중한 고려로 이어지기를 바란다.","diff":["overcome these challenges through careful consideration of neuroethics","overcoming these challenges will lead to careful consideration of neuroethics","신경 윤리 고려를 통해(수단) → 난제 극복(목표)","난제 극복 → 신경 윤리 고려로 이어짐(뒤집음)"],"y":"\"we can overcome these challenges through careful consideration of neuroethics\" (신경 윤리를 신중하게 고려함으로써 이러한 난제들을 극복할 수 있다)\n원문은 신경 윤리를 고려하는 것이 수단이고 난제 극복이 목표인데, 바꾼 문장은 그 순서를 뒤집어서 달라요.\n수단↔결과 뒤집기: through(~을 통해)는 수단. lead to로 바꾸면서 수단과 결과 자리만 맞바꿈, 단어가 같아 속기 쉬움","t":"수단↔결과 뒤집기"}]},{"id":"g4-14","src":"본문","where":"섹션5: ⑤ 신경 윤리와 댓글","en":"I think it is important to establish a prior review process and thoroughly assess the ethical aspects before any kind of brain research is conducted. This will ensure that science and technology progress in accordance with ethical principles.","ko":"나는 어떤 종류의 뇌 연구든 진행되기 전에 사전 검토 절차를 마련하고 윤리적 측면을 철저히 평가하는 것이 중요하다고 생각한다. 이렇게 하면 과학과 기술이 윤리 원칙에 따라 발전하도록 보장될 것이다.","v":[{"en":"A prior review process will make sure that science and technology develop according to ethical principles.","same":true,"ko":"사전 검토 절차는 과학과 기술이 윤리 원칙에 따라 발전하도록 확실히 해 줄 것이다.","n":"This(지시어) 풀기, ensure = make sure, in accordance with = according to","sw":[["This will ensure that","will make sure that","이것은 ~을 보장할 것이다 ↔ ~을 확실히 해 줄 것이다"],["progress in accordance with ethical principles","develop according to ethical principles","윤리 원칙에 따라 발전하다 ↔ 윤리 원칙에 따라 발전하다"]]},{"en":"In the writer's opinion, a prior review process should be set up before brain research is carried out.","same":true,"ko":"글쓴이의 생각으로는, 뇌 연구가 진행되기 전에 사전 검토 절차가 마련되어야 한다.","n":"it is important to ~ = should ~ (수동태로)","sw":[["it is important to establish a prior review process","a prior review process should be set up","사전 검토 절차를 마련하는 것이 중요하다 ↔ 사전 검토 절차가 마련되어야 한다"],["before any kind of brain research is conducted","before brain research is carried out","어떤 뇌 연구든 진행되기 전에 ↔ 뇌 연구가 진행되기 전에"]]},{"en":"The writer believes that once science and technology progress in accordance with ethical principles, a prior review process will no longer be necessary.","same":false,"ko":"필자는 과학과 기술이 윤리 원칙에 따라 발전하게 되면 사전 검토 절차가 더는 필요하지 않을 것이라고 믿는다.","diff":["it is important to establish a prior review process","a prior review process will no longer be necessary","사전 검토 절차를 마련하는 것이 중요하다","사전 검토 절차가 더는 필요 없다"],"y":"\"it is important to establish a prior review process\" (사전 검토 절차를 마련하는 것이 중요하다)\n원문은 사전 검토가 중요하고 그것이 윤리적 발전을 보장한다고 했는데, 바꾼 문장은 검토가 필요 없어진다고 해서 달라요.\n수단·목적 관계 왜곡: 검토(수단)가 윤리적 발전(결과)을 보장하는 관계. 결과를 앞세워 수단을 지워 버리면 오답","t":"수단·목적 관계 왜곡"},{"en":"The ethical aspects of brain research should be thoroughly assessed in advance.","same":true,"ko":"뇌 연구의 윤리적 측면은 미리 철저하게 평가되어야 한다.","n":"before ~ is conducted = in advance(미리), 능동 → 수동","sw":[["thoroughly assess the ethical aspects before any kind of brain research is conducted","The ethical aspects of brain research should be thoroughly assessed in advance","뇌 연구 전에 윤리적 측면을 철저히 평가하다 ↔ 뇌 연구의 윤리적 측면이 미리 철저히 평가되어야 한다"]]},{"en":"The writer thinks that not every kind of brain research needs to have its ethical aspects assessed in advance.","same":false,"ko":"필자는 모든 종류의 뇌 연구가 윤리적 측면을 미리 평가받아야 하는 것은 아니라고 생각한다.","diff":["before any kind of brain research is conducted","not every kind of brain research needs","어떤 종류의 뇌 연구든(전부) 전에","모든 뇌 연구가 그래야 하는 건 아님(부분 부정)"],"y":"\"thoroughly assess the ethical aspects before any kind of brain research is conducted\" (어떤 종류의 뇌 연구든 진행되기 전에 윤리적 측면을 철저히 평가한다)\n원문은 어떤 종류의 연구든 예외 없이 미리 평가하라고 했는데, 바꾼 문장은 일부는 안 해도 된다고 해서 달라요.\n부분 부정(not every): any kind = 예외 없이 전부. not every는 '전부는 아님'(일부는 제외). in advance가 맞아서 같은 말로 착각하기 쉬움","t":"부분 부정(not every)"},{"en":"Brain researchers are already required to go through a prior review process before conducting any kind of research.","same":false,"ko":"뇌 연구자들은 어떤 종류의 연구든 진행하기 전에 이미 사전 검토 절차를 거치도록 되어 있다.","diff":["I think it is important to establish a prior review process","are already required to go through a prior review process","필자 의견: 사전 검토 절차를 마련하는 것이 중요하다(아직 없음)","사실: 이미 사전 검토 절차를 거치게 되어 있다"],"y":"\"I think it is important to establish a prior review process\" (나는 사전 검토 절차를 마련하는 것이 중요하다고 생각한다)\n원문은 필자가 사전 검토 절차를 새로 마련해야 한다고 주장했는데, 바꾼 문장은 이미 그런 절차가 있다고 해서 달라요.\n의견·제안 → 이미 있는 사실: prior review process, before, any kind of research가 그대로라 같은 말 같지만, establish(마련하다)는 아직 없다는 뜻","t":"의견·제안 → 이미 있는 사실"}]},{"id":"g4-15","src":"본문","where":"섹션5: ⑤ 신경 윤리와 댓글","en":"Yumi Lee: Well, the technology sounds amazing, but I'm really worried about the privacy issues it might cause. I think it is necessary to strictly enforce privacy laws to protect the personal information of individuals.","ko":"Yumi Lee: 음, 이 기술은 놀라워 보이지만, 이것이 일으킬 수 있는 사생활 문제가 정말 걱정돼요. 개인의 개인 정보를 보호하기 위해 개인 정보 보호법을 엄격하게 시행해야 한다고 생각해요.","v":[{"en":"According to Yumi Lee, privacy laws should be strictly enforced so that individuals' personal information is protected.","same":true,"ko":"Yumi Lee에 따르면, 개인의 개인 정보가 보호되도록 개인 정보 보호법이 엄격하게 시행되어야 한다.","n":"목적의 to부정사 = so that 절, 능동 → 수동","sw":[["it is necessary to strictly enforce privacy laws","privacy laws should be strictly enforced","개인 정보 보호법을 엄격히 시행할 필요가 있다 ↔ 개인 정보 보호법이 엄격히 시행되어야 한다"],["to protect the personal information of individuals","so that individuals' personal information is protected","개인의 개인 정보를 보호하기 위해 ↔ 개인의 개인 정보가 보호되도록"]]},{"en":"Yumi Lee thinks privacy laws need not be strictly enforced as long as personal information is protected.","same":false,"ko":"Yumi Lee는 개인 정보가 보호되기만 하면 개인 정보 보호법을 엄격하게 시행할 필요는 없다고 생각한다.","diff":["it is necessary to strictly enforce privacy laws","privacy laws need not be strictly enforced","법을 엄격하게 시행할 필요가 있다","엄격하게 시행할 필요는 없다"],"y":"\"I think it is necessary to strictly enforce privacy laws to protect the personal information of individuals\" (개인의 개인 정보를 보호하기 위해 개인 정보 보호법을 엄격하게 시행해야 한다고 생각해요)\nYumi Lee는 정보를 지키려면 법을 엄격히 시행해야 한다고 했는데, 바꾼 문장은 그럴 필요가 없다고 해서 반대예요.\n필요성 부정(조건 붙이기): need not = '~할 필요 없다'. as long as(~하기만 하면) 조건이 그럴듯해서 속기 쉬움, 원문은 법 시행이 정보 보호의 수단","t":"필요성 부정(조건 붙이기)"},{"en":"Yumi Lee is worried about the privacy issues that the technology has already caused.","same":false,"ko":"Yumi Lee는 이 기술이 이미 일으킨 사생활 문제를 걱정한다.","diff":["the privacy issues it might cause","the privacy issues that the technology has already caused","일으킬 수도 있는 사생활 문제","이미 일으킨 사생활 문제"],"y":"\"I'm really worried about the privacy issues it might cause\" (이것이 일으킬 수 있는 사생활 문제가 정말 걱정돼요)\n원문은 앞으로 생길 수도 있는 문제를 걱정했는데, 바꾼 문장은 이미 생긴 문제라고 해서 달라요.\n가능성↔사실: worried가 맞아서 같은 말로 보이지만 might cause(~할지도)와 has already caused는 다름","t":"가능성↔사실"},{"en":"Since Yumi Lee is worried about privacy issues, she finds the technology anything but amazing.","same":false,"ko":"Yumi Lee는 사생활 문제가 걱정되기 때문에 이 기술이 전혀 놀랍지 않다고 여긴다.","diff":["the technology sounds amazing, but","she finds the technology anything but amazing","기술은 놀랍지만(인정) 걱정된다","걱정되므로 기술이 전혀 놀랍지 않다"],"y":"\"the technology sounds amazing, but I'm really worried about the privacy issues\" (이 기술은 놀라워 보이지만, 사생활 문제가 정말 걱정돼요)\n원문은 기술이 놀랍다고 인정한 뒤 걱정을 말했는데, 바꾼 문장은 걱정 때문에 전혀 놀랍지 않다고 해서 달라요.\n양보↔인과 뒤집기: anything but = '결코 ~가 아닌'(not at all). amazing이 그대로 있어 긍정으로 착각하기 쉬움, but(양보)을 since(이유)로 바꾼 것도 함정","t":"양보↔인과 뒤집기"},{"en":"Although Yumi Lee finds the technology amazing, she is concerned about the privacy problems it could cause.","same":true,"ko":"Yumi Lee는 이 기술이 놀랍다고 생각하지만, 이 기술이 일으킬 수 있는 사생활 문제를 걱정한다.","n":"A, but B = Although A, B (양보 접속사로 바꾸기)","sw":[["the technology sounds amazing, but","Although Yumi Lee finds the technology amazing,","기술이 놀라워 보이지만 ↔ Yumi Lee는 기술이 놀랍다고 생각하지만"],["I'm really worried about","she is concerned about","나는 정말 걱정된다 ↔ 그녀는 걱정한다"]]},{"en":"Yumi Lee believes strict enforcement of privacy laws is needed to keep individuals' personal information safe.","same":true,"ko":"Yumi Lee는 개인의 개인 정보를 안전하게 지키려면 개인 정보 보호법의 엄격한 시행이 필요하다고 믿는다.","n":"동사구(strictly enforce) → 명사구(strict enforcement)로 명사화","sw":[["strictly enforce privacy laws","strict enforcement of privacy laws","개인 정보 보호법을 엄격히 시행하다 ↔ 개인 정보 보호법의 엄격한 시행"],["to protect the personal information of individuals","to keep individuals' personal information safe","개인의 개인 정보를 보호하기 위해 ↔ 개인의 개인 정보를 안전하게 지키기 위해"]]}]}];
